/// Pure capture decision; no pasteboard, workspace or settings access.
enum CapturePolicy {
    static let sensitiveMarkers = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
    ]

    static let defaultExcludedAppBundleIDs = ["com.apple.keychainaccess", "com.apple.Passwords"]

    static func shouldSave(types: [String], sourceBundleID: String?, excludedAppBundleIDs: [String],
                           isPaused: Bool, ignoreConcealed: Bool) -> Bool {
        guard !isPaused else { return false }
        if let bundleID = sourceBundleID, excludedAppBundleIDs.contains(bundleID) { return false }
        return !ignoreConcealed || !types.contains { sensitiveMarkers.contains($0) }
    }
}
